<script setup lang="ts">
import { AlertCircle, CheckCircle2, Clock3, Headphones, MessageSquare, Plus, RefreshCw, Search, Send, Users, X } from '@lucide/vue';
const config = useRuntimeConfig();
const route = useRoute();
const props = defineProps<{ pageSection?: string }>();
const { token, user } = useWorkspaceSession();
const { openContextMenu, copyText } = useContextMenu();
const dashboard = ref<any>(null);
const tickets = ref<any[]>([]);
const agents = ref<any[]>([]);
const selected = ref<any>(null);
const createOpen = ref(false);
const loading = ref(false);
const error = ref('');
const notice = ref('');
const search = ref('');
const statusFilter = ref('');
const sourceFilter = ref('');
const comment = ref('');
const internalComment = ref(false);
const actionBusy = ref(false);
const queueFilter = computed(() => typeof route.query.queue === 'string' ? route.query.queue : '');
const section = computed(() => props.pageSection || String(route.query.section || 'overview'));
let loadVersion = 0;
let loadController: AbortController | undefined;
const form = reactive({ subject:'', description:'', source:'EMPLOYEE', priority:'MEDIUM', affectedService:'Workspace' });
const statusLabels:Record<string,string> = { NEW:'Новая',OPEN:'В работе',WAITING_REQUESTER:'Ждём заявителя',WAITING_INTERNAL:'Внутреннее ожидание',RESOLVED:'Решена',CLOSED:'Закрыта' };
const priorityLabels:Record<string,string> = { LOW:'Низкий',MEDIUM:'Обычный',HIGH:'Высокий',CRITICAL:'Критический' };
const sourceLabels:Record<string,string> = { EMPLOYEE:'Сотрудник',B2C:'Клиент B2C',B2B:'Клиент B2B',SYSTEM:'Система' };
const filtered = computed(() => tickets.value.filter(ticket => (!queueFilter.value || (ticket.queue || 'Первая линия') === queueFilter.value) && (!statusFilter.value || ticket.status === statusFilter.value) && (!sourceFilter.value || ticket.source === sourceFilter.value) && (!search.value || `${ticket.number} ${ticket.subject} ${ticket.requesterEmail || ''}`.toLowerCase().includes(search.value.toLowerCase()))));
const queues = computed(() => Array.from(new Set(tickets.value.map(ticket => ticket.queue || 'Первая линия'))).map(queue => ({ name:queue, total:tickets.value.filter(ticket => (ticket.queue || 'Первая линия') === queue).length, open:tickets.value.filter(ticket => (ticket.queue || 'Первая линия') === queue && !['RESOLVED','CLOSED'].includes(ticket.status)).length })));
const slaState = (ticket:any) => ticket.resolutionDueAt && new Date(ticket.resolutionDueAt) < new Date() && !['RESOLVED','CLOSED'].includes(ticket.status) ? 'Просрочена' : 'В срок';
function requester(ticket:any) { return [ticket.requesterUser?.firstName,ticket.requesterUser?.lastName].filter(Boolean).join(' ') || ticket.requesterName || ticket.requesterEmail || sourceLabels[ticket.source]; }
async function load() {
  if (!token.value || section.value === 'knowledge') return;
  const version = ++loadVersion, identity = token.value;
  loadController?.abort(); const controller = new AbortController(); loadController = controller;
  loading.value = true; error.value = '';
  try {
    const options = { baseURL: config.public.apiBase, headers: { Authorization: `Bearer ${identity}` }, signal: controller.signal, timeout: 20000 };
    const [nextDashboard, nextTickets, nextAgents] = await Promise.all([
      section.value === 'overview' ? $fetch('/helpdesk/dashboard', options) : Promise.resolve(null),
      $fetch<any[]>('/helpdesk/tickets', options),
      section.value === 'tickets' ? $fetch<any[]>('/helpdesk/agents', options) : Promise.resolve(null),
    ]);
    if (version !== loadVersion || token.value !== identity) return;
    if (nextDashboard) dashboard.value = nextDashboard;
    tickets.value = nextTickets;
    if (nextAgents) agents.value = nextAgents;
    if (selected.value) selected.value = tickets.value.find(ticket => ticket.id === selected.value.id) || null;
  } catch (e: any) { if (version === loadVersion && token.value === identity && !controller.signal.aborted) error.value = typeof e?.data?.message === 'string' ? e.data.message : 'Не удалось загрузить поддержку. Повторите попытку.'; }
  finally { if (version === loadVersion) loading.value = false; }
}
onUnmounted(() => { ++loadVersion; loadController?.abort(); });
function fail(e:any) { error.value = Array.isArray(e?.data?.message) ? e.data.message.join(', ') : e?.data?.message || 'Действие не выполнено. Повторите попытку.'; }
async function createTicket(){
  if(actionBusy.value)return; actionBusy.value=true; error.value='';
  try{await $fetch('/helpdesk/tickets',{baseURL:config.public.apiBase,method:'POST',headers:{Authorization:`Bearer ${token.value}`},body:{...form}});Object.assign(form,{subject:'',description:'',source:'EMPLOYEE',priority:'MEDIUM',affectedService:'Workspace'});createOpen.value=false;notice.value='Заявка создана';await load();setTimeout(()=>notice.value='',2200);}
  catch(e:any){fail(e);} finally{actionBusy.value=false;}
}
async function updateTicket(ticket:any, field:string, value:string|null){
  if(actionBusy.value)return; actionBusy.value=true; error.value='';
  try{const updated=await $fetch<any>(`/helpdesk/tickets/${ticket.id}`,{baseURL:config.public.apiBase,method:'PATCH',headers:{Authorization:`Bearer ${token.value}`},body:{[field]:field==='assignedToId' ? value || null : value}});Object.assign(ticket,updated);notice.value='Заявка обновлена';setTimeout(()=>notice.value='',1800);}
  catch(e:any){fail(e);} finally{actionBusy.value=false;}
}
async function changeTicket(event:Event,ticket:any,field:string){
  const input=event.target as HTMLInputElement;
  await updateTicket(ticket,field,input.value);
  input.value=ticket[field] || '';
}
async function addComment(){
  if(!comment.value.trim()||!selected.value||actionBusy.value)return;
  const ticket=selected.value; actionBusy.value=true; error.value='';
  try{const created=await $fetch<any>(`/helpdesk/tickets/${ticket.id}/comments`,{baseURL:config.public.apiBase,method:'POST',headers:{Authorization:`Bearer ${token.value}`},body:{body:comment.value.trim(),isInternal:internalComment.value}});ticket.comments=[...(ticket.comments||[]),{...created,author:created.author||user.value}];comment.value='';internalComment.value=false;notice.value='Комментарий отправлен';setTimeout(()=>notice.value='',1800);}
  catch(e:any){fail(e);} finally{actionBusy.value=false;}
}
function closeTicket(){if(actionBusy.value || (comment.value.trim() && !window.confirm('Отменить неотправленный комментарий?')))return false;selected.value=null;comment.value='';internalComment.value=false;return true;}
function openTicket(ticket:any){if(closeTicket()){selected.value=ticket;error.value='';}}
function openQueue(queue:string){return navigateTo({path:'/helpdesk',query:{...route.query,section:'tickets',queue}});}
function resetFilters(){search.value='';statusFilter.value='';sourceFilter.value='';const query={...route.query};delete query.queue;delete query.section;return navigateTo({path:'/helpdesk/tickets',query});}
onBeforeRouteLeave(() => !actionBusy.value && (!comment.value.trim() || window.confirm('Уйти без отправки комментария?')));
function ticketMenu(event:MouseEvent,ticket:any){openContextMenu(event,ticket.number,[{label:'Открыть заявку',icon:'open',action:()=>openTicket(ticket)},{label:'Копировать номер',icon:'copy',action:()=>copyText(ticket.number,'Номер заявки скопирован')},...(!['OPEN','RESOLVED','CLOSED'].includes(ticket.status)?[{label:'Взять в работу',icon:'status' as const,separator:true,disabled:actionBusy.value,action:()=>updateTicket(ticket,'status','OPEN')}]:[]),...(!['RESOLVED','CLOSED'].includes(ticket.status)?[{label:'Отметить решённой',icon:'status' as const,disabled:actionBusy.value,action:()=>updateTicket(ticket,'status','RESOLVED')}]:[])],requester(ticket));}
onMounted(load);
</script>

<template><main data-v-ui-9200e9d7b7db class="helpdesk-page"><header data-v-ui-9200e9d7b7db class="hd-header"><div data-v-ui-9200e9d7b7db><p data-v-ui-9200e9d7b7db class="eyebrow">IT HELPDESK / ЕДИНАЯ ПОДДЕРЖКА</p><h1 data-v-ui-9200e9d7b7db>{{ section === 'tickets' ? 'Все заявки' : section === 'queues' ? 'Очереди поддержки' : section === 'knowledge' ? 'База знаний' : 'Центр поддержки' }}</h1><span data-v-ui-9200e9d7b7db>Сотрудники, B2C и B2B · единая очередь обращений</span></div><div data-v-ui-9200e9d7b7db><button data-v-ui-9200e9d7b7db class="outline" :disabled="loading || actionBusy" @click="load"><RefreshCw data-v-ui-9200e9d7b7db :size="16" :class="{spin:loading}" /> Обновить</button><button data-v-ui-9200e9d7b7db class="primary" :disabled="actionBusy" @click="createOpen=true"><Plus data-v-ui-9200e9d7b7db :size="16" /> Новая заявка</button></div></header><p data-v-ui-9200e9d7b7db v-if="error" class="operation-error" role="alert">{{ error }}</p><WorkspaceLoading v-if="!dashboard && loading" label="Загружаем обращения" /><div data-v-ui-9200e9d7b7db v-else-if="error && !dashboard" class="state-error"><AlertCircle data-v-ui-9200e9d7b7db :size="22" /><span data-v-ui-9200e9d7b7db>{{ error }}</span><button data-v-ui-9200e9d7b7db @click="load">Повторить</button></div><div data-v-ui-9200e9d7b7db v-else class="hd-body">
  <template v-if="section === 'overview'"><section data-v-ui-9200e9d7b7db class="hd-kpis"><article data-v-ui-9200e9d7b7db><span data-v-ui-9200e9d7b7db>Новые</span><strong data-v-ui-9200e9d7b7db class="coral">{{ dashboard?.new || 0 }}</strong><small data-v-ui-9200e9d7b7db>ещё не распределены</small></article><article data-v-ui-9200e9d7b7db><span data-v-ui-9200e9d7b7db>В работе</span><strong data-v-ui-9200e9d7b7db>{{ dashboard?.inWork || 0 }}</strong><small data-v-ui-9200e9d7b7db>есть исполнитель</small></article><article data-v-ui-9200e9d7b7db><span data-v-ui-9200e9d7b7db>Ожидают</span><strong data-v-ui-9200e9d7b7db>{{ dashboard?.waiting || 0 }}</strong><small data-v-ui-9200e9d7b7db>ответа или действия</small></article><article data-v-ui-9200e9d7b7db><span data-v-ui-9200e9d7b7db>Просрочены</span><strong data-v-ui-9200e9d7b7db :class="{'red':dashboard?.overdue}">{{ dashboard?.overdue || 0 }}</strong><small data-v-ui-9200e9d7b7db>нарушен SLA</small></article></section><section data-v-ui-9200e9d7b7db class="hd-grid"><article data-v-ui-9200e9d7b7db class="panel"><div data-v-ui-9200e9d7b7db class="panel-head"><div data-v-ui-9200e9d7b7db><p data-v-ui-9200e9d7b7db class="eyebrow">ОПЕРАЦИОННАЯ ОЧЕРЕДЬ</p><h2 data-v-ui-9200e9d7b7db>Требуют внимания</h2></div><NuxtLink data-v-ui-9200e9d7b7db to="/helpdesk?section=tickets">Все заявки</NuxtLink></div><div data-v-ui-9200e9d7b7db v-for="ticket in tickets.filter(t=>!['RESOLVED','CLOSED'].includes(t.status)).slice(0,6)" :key="ticket.id" class="ticket-compact" role="button" tabindex="0" @keydown.enter="openTicket(ticket)" @keydown.space.prevent="openTicket(ticket)" @click="openTicket(ticket)" @contextmenu.prevent="ticketMenu($event,ticket)"><i data-v-ui-9200e9d7b7db :class="`priority-${ticket.priority.toLowerCase()}`"></i><span data-v-ui-9200e9d7b7db><strong data-v-ui-9200e9d7b7db>{{ ticket.subject }}</strong><small data-v-ui-9200e9d7b7db>{{ ticket.number }} · {{ requester(ticket) }}</small></span><b data-v-ui-9200e9d7b7db :class="{'overdue':slaState(ticket)==='Просрочена'}">{{ slaState(ticket) }}</b></div><p data-v-ui-9200e9d7b7db v-if="!tickets.length" class="empty">Обращений пока нет</p></article><article data-v-ui-9200e9d7b7db class="panel"><div data-v-ui-9200e9d7b7db class="panel-head"><div data-v-ui-9200e9d7b7db><p data-v-ui-9200e9d7b7db class="eyebrow">ИСТОЧНИКИ</p><h2 data-v-ui-9200e9d7b7db>Откуда обращаются</h2></div></div><div data-v-ui-9200e9d7b7db v-for="source in ['EMPLOYEE','B2C','B2B','SYSTEM']" :key="source" class="source-row"><span data-v-ui-9200e9d7b7db>{{ sourceLabels[source] }}</span><b data-v-ui-9200e9d7b7db>{{ tickets.filter(ticket=>ticket.source===source).length }}</b><i data-v-ui-9200e9d7b7db><em data-v-ui-9200e9d7b7db :style="{width:`${tickets.length ? tickets.filter(ticket=>ticket.source===source).length/tickets.length*100 : 0}%`}"></em></i></div></article></section></template>
  <template v-else-if="section === 'tickets'"><section data-v-ui-9200e9d7b7db class="panel ticket-panel"><p data-v-ui-9200e9d7b7db v-if="queueFilter" class="queue-label">Очередь: {{ queueFilter }}</p><div data-v-ui-9200e9d7b7db class="filters"><label data-v-ui-9200e9d7b7db><Search data-v-ui-9200e9d7b7db :size="16" /><input data-v-ui-9200e9d7b7db v-model="search" placeholder="Номер, тема или заявитель" /></label><select data-v-ui-9200e9d7b7db v-model="statusFilter"><option data-v-ui-9200e9d7b7db value="">Все статусы</option><option data-v-ui-9200e9d7b7db v-for="(label,id) in statusLabels" :key="id" :value="id">{{ label }}</option></select><select data-v-ui-9200e9d7b7db v-model="sourceFilter"><option data-v-ui-9200e9d7b7db value="">Все источники</option><option data-v-ui-9200e9d7b7db v-for="(label,id) in sourceLabels" :key="id" :value="id">{{ label }}</option></select><button data-v-ui-9200e9d7b7db v-if="search||statusFilter||sourceFilter||queueFilter" @click="resetFilters">Сбросить</button></div><div data-v-ui-9200e9d7b7db class="ticket-table"><div data-v-ui-9200e9d7b7db class="ticket-row head"><span data-v-ui-9200e9d7b7db>Заявка</span><span data-v-ui-9200e9d7b7db>Заявитель</span><span data-v-ui-9200e9d7b7db>Источник</span><span data-v-ui-9200e9d7b7db>Приоритет</span><span data-v-ui-9200e9d7b7db>Статус</span><span data-v-ui-9200e9d7b7db>SLA</span></div><div data-v-ui-9200e9d7b7db v-for="ticket in filtered" :key="ticket.id" class="ticket-row" role="button" tabindex="0" @keydown.enter="openTicket(ticket)" @keydown.space.prevent="openTicket(ticket)" @click="openTicket(ticket)" @contextmenu.prevent="ticketMenu($event,ticket)"><div data-v-ui-9200e9d7b7db><strong data-v-ui-9200e9d7b7db>{{ ticket.subject }}</strong><small data-v-ui-9200e9d7b7db>{{ ticket.number }} · {{ new Date(ticket.createdAt).toLocaleString('ru-RU') }}</small></div><span data-v-ui-9200e9d7b7db>{{ requester(ticket) }}</span><span data-v-ui-9200e9d7b7db>{{ sourceLabels[ticket.source] }}</span><span data-v-ui-9200e9d7b7db :class="`text-${ticket.priority.toLowerCase()}`">{{ priorityLabels[ticket.priority] }}</span><span data-v-ui-9200e9d7b7db>{{ statusLabels[ticket.status] }}</span><span data-v-ui-9200e9d7b7db :class="{'red':slaState(ticket)==='Просрочена'}">{{ slaState(ticket) }}</span></div><p data-v-ui-9200e9d7b7db v-if="!filtered.length" class="empty">По заданным условиям заявок нет</p></div></section></template>
  <template v-else-if="section === 'queues'"><section data-v-ui-9200e9d7b7db class="queue-grid"><article data-v-ui-9200e9d7b7db v-for="queue in queues" :key="queue.name"><div data-v-ui-9200e9d7b7db><Users data-v-ui-9200e9d7b7db :size="19" /><span data-v-ui-9200e9d7b7db>{{ queue.name }}</span></div><strong data-v-ui-9200e9d7b7db>{{ queue.open }}</strong><small data-v-ui-9200e9d7b7db>в работе · всего {{ queue.total }}</small><button data-v-ui-9200e9d7b7db @click="openQueue(queue.name)">Открыть очередь</button></article><article data-v-ui-9200e9d7b7db v-if="!queues.length" class="empty-card">Очереди появятся после первой заявки</article></section></template>
  <template v-else><section data-v-ui-9200e9d7b7db class="knowledge"><div data-v-ui-9200e9d7b7db><p data-v-ui-9200e9d7b7db class="eyebrow">САМООБСЛУЖИВАНИЕ</p><h2 data-v-ui-9200e9d7b7db>База знаний</h2><span data-v-ui-9200e9d7b7db class="knowledge-status">Скоро</span><p data-v-ui-9200e9d7b7db>Раздел пока недоступен: инструкции и готовые ответы ещё готовятся. Если нужна помощь сейчас, создайте заявку кнопкой «Новая заявка».</p></div><div data-v-ui-9200e9d7b7db class="knowledge-grid"><article data-v-ui-9200e9d7b7db><Headphones data-v-ui-9200e9d7b7db :size="20" /><h3 data-v-ui-9200e9d7b7db>Рабочие системы</h3><p data-v-ui-9200e9d7b7db>Вход, права доступа и работа внутренних кабинетов.</p><span data-v-ui-9200e9d7b7db>Материалы готовятся</span></article><article data-v-ui-9200e9d7b7db><MessageSquare data-v-ui-9200e9d7b7db :size="20" /><h3 data-v-ui-9200e9d7b7db>Клиентский сервис</h3><p data-v-ui-9200e9d7b7db>Ответы по заказам, оплате, доставке и возвратам.</p><span data-v-ui-9200e9d7b7db>Материалы готовятся</span></article><article data-v-ui-9200e9d7b7db><CheckCircle2 data-v-ui-9200e9d7b7db :size="20" /><h3 data-v-ui-9200e9d7b7db>1С и интеграции</h3><p data-v-ui-9200e9d7b7db>Синхронизация товаров, остатков и каналов продаж.</p><span data-v-ui-9200e9d7b7db>Материалы готовятся</span></article></div></section></template>
</div>
<aside data-v-ui-9200e9d7b7db v-if="createOpen" class="backdrop admin-dialog-backdrop" @click.self="!actionBusy && (createOpen=false)"><form data-v-ui-9200e9d7b7db class="drawer create admin-dialog admin-dialog--drawer" @submit.prevent="createTicket"><header data-v-ui-9200e9d7b7db><div data-v-ui-9200e9d7b7db><p data-v-ui-9200e9d7b7db class="eyebrow">НОВОЕ ОБРАЩЕНИЕ</p><h2 data-v-ui-9200e9d7b7db>Создать заявку</h2></div><button data-v-ui-9200e9d7b7db type="button" :disabled="actionBusy" @click="createOpen=false"><X data-v-ui-9200e9d7b7db :size="18" /></button></header><div data-v-ui-9200e9d7b7db class="drawer-scroll admin-dialog-body"><p data-v-ui-9200e9d7b7db v-if="error" class="operation-error" role="alert">{{ error }}</p><fieldset data-v-ui-9200e9d7b7db ui-inline-i-9200e9d7b7db-1 :disabled="actionBusy" ><label data-v-ui-9200e9d7b7db>Тема<input data-v-ui-9200e9d7b7db v-model="form.subject" required placeholder="Кратко опишите проблему" /></label><label data-v-ui-9200e9d7b7db>Подробное описание<textarea data-v-ui-9200e9d7b7db v-model="form.description" rows="7" required placeholder="Что произошло и какой результат ожидался" /></label><div data-v-ui-9200e9d7b7db class="two"><label data-v-ui-9200e9d7b7db>Источник<select data-v-ui-9200e9d7b7db v-model="form.source"><option data-v-ui-9200e9d7b7db v-for="(label,id) in sourceLabels" :key="id" :value="id">{{ label }}</option></select></label><label data-v-ui-9200e9d7b7db>Приоритет<select data-v-ui-9200e9d7b7db v-model="form.priority"><option data-v-ui-9200e9d7b7db v-for="(label,id) in priorityLabels" :key="id" :value="id">{{ label }}</option></select></label></div><label data-v-ui-9200e9d7b7db>Затронутый сервис<input data-v-ui-9200e9d7b7db v-model="form.affectedService" placeholder="Например, 1С или личный кабинет" /></label><div data-v-ui-9200e9d7b7db class="sla-note"><Clock3 data-v-ui-9200e9d7b7db :size="17" /><span data-v-ui-9200e9d7b7db><strong data-v-ui-9200e9d7b7db>SLA будет рассчитан автоматически</strong><small data-v-ui-9200e9d7b7db>По источнику, приоритету и рабочему календарю поддержки.</small></span></div></fieldset></div><footer data-v-ui-9200e9d7b7db><button data-v-ui-9200e9d7b7db type="button" :disabled="actionBusy" @click="createOpen=false">Отмена</button><button data-v-ui-9200e9d7b7db class="primary" :disabled="actionBusy">{{ actionBusy ? 'Создаём…' : 'Создать заявку' }}</button></footer></form></aside>
<aside data-v-ui-9200e9d7b7db v-if="selected" class="backdrop admin-dialog-backdrop" @click.self="closeTicket"><section data-v-ui-9200e9d7b7db class="drawer ticket-detail admin-dialog admin-dialog--drawer"><header data-v-ui-9200e9d7b7db><div data-v-ui-9200e9d7b7db><p data-v-ui-9200e9d7b7db class="eyebrow">{{ selected.number }}</p><h2 data-v-ui-9200e9d7b7db>{{ selected.subject }}</h2><span data-v-ui-9200e9d7b7db>{{ sourceLabels[selected.source] }} · {{ requester(selected) }}</span></div><button data-v-ui-9200e9d7b7db aria-label="Закрыть заявку" :disabled="actionBusy" @click="closeTicket"><X data-v-ui-9200e9d7b7db :size="18" /></button></header><div data-v-ui-9200e9d7b7db class="drawer-scroll admin-dialog-body"><p data-v-ui-9200e9d7b7db v-if="error" class="operation-error" role="alert">{{ error }}</p><fieldset data-v-ui-9200e9d7b7db ui-inline-i-9200e9d7b7db-2 class="control-grid" :disabled="actionBusy" ><label data-v-ui-9200e9d7b7db>Статус<select data-v-ui-9200e9d7b7db :value="selected.status" @change="changeTicket($event,selected,'status')"><option data-v-ui-9200e9d7b7db v-for="(label,id) in statusLabels" :key="id" :value="id">{{ label }}</option></select></label><label data-v-ui-9200e9d7b7db>Приоритет<select data-v-ui-9200e9d7b7db :value="selected.priority" @change="changeTicket($event,selected,'priority')"><option data-v-ui-9200e9d7b7db v-for="(label,id) in priorityLabels" :key="id" :value="id">{{ label }}</option></select></label><label data-v-ui-9200e9d7b7db>Исполнитель<select data-v-ui-9200e9d7b7db :value="selected.assignedToId||''" @change="changeTicket($event,selected,'assignedToId')"><option data-v-ui-9200e9d7b7db value="">Не назначен</option><option data-v-ui-9200e9d7b7db v-for="agent in agents" :key="agent.id" :value="agent.id">{{ [agent.firstName,agent.lastName].filter(Boolean).join(' ')||agent.email }}</option></select></label><label data-v-ui-9200e9d7b7db>Очередь<input data-v-ui-9200e9d7b7db :value="selected.queue" @change="changeTicket($event,selected,'queue')" /></label></fieldset><p data-v-ui-9200e9d7b7db class="muted">Изменения полей сохраняются сразу. Допустимость действия проверяет сервер.</p><div data-v-ui-9200e9d7b7db class="ticket-actions"><button data-v-ui-9200e9d7b7db v-if="!['OPEN','RESOLVED','CLOSED'].includes(selected.status)" :disabled="actionBusy" @click="updateTicket(selected,'status','OPEN')">Взять в работу</button><button data-v-ui-9200e9d7b7db v-if="!['RESOLVED','CLOSED'].includes(selected.status)" :disabled="actionBusy" @click="updateTicket(selected,'status','RESOLVED')">Решить заявку</button><button data-v-ui-9200e9d7b7db :disabled="actionBusy" @click="copyText(selected.number,'Номер заявки скопирован')">Копировать номер</button></div><section data-v-ui-9200e9d7b7db class="request-text"><h3 data-v-ui-9200e9d7b7db>Описание</h3><p data-v-ui-9200e9d7b7db>{{ selected.description }}</p></section><section data-v-ui-9200e9d7b7db class="comments"><h3 data-v-ui-9200e9d7b7db>Обсуждение</h3><div data-v-ui-9200e9d7b7db v-for="item in selected.comments" :key="item.id" :class="['comment',{internal:item.isInternal}]"><div data-v-ui-9200e9d7b7db><strong data-v-ui-9200e9d7b7db>{{ [item.author?.firstName,item.author?.lastName].filter(Boolean).join(' ')||item.author?.email||'Заявитель' }}</strong><span data-v-ui-9200e9d7b7db v-if="item.isInternal">Внутренний комментарий</span><small data-v-ui-9200e9d7b7db>{{ new Date(item.createdAt).toLocaleString('ru-RU') }}</small></div><p data-v-ui-9200e9d7b7db>{{ item.body }}</p></div><p data-v-ui-9200e9d7b7db v-if="!selected.comments?.length" class="empty">Комментариев пока нет</p></section></div><footer data-v-ui-9200e9d7b7db class="reply"><textarea data-v-ui-9200e9d7b7db v-model="comment" :disabled="actionBusy" rows="2" placeholder="Написать ответ"></textarea><label data-v-ui-9200e9d7b7db><input data-v-ui-9200e9d7b7db v-model="internalComment" :disabled="actionBusy" type="checkbox" /> Только для сотрудников</label><button data-v-ui-9200e9d7b7db class="send" aria-label="Отправить комментарий" :disabled="actionBusy || !comment.trim()" @click="addComment"><Send data-v-ui-9200e9d7b7db :size="16" />{{ actionBusy ? 'Отправляем…' : 'Отправить' }}</button></footer></section></aside><div data-v-ui-9200e9d7b7db v-if="notice" class="toast">{{ notice }}</div></main></template>


